INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g6_1_kor_u5_L01_basic#1','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C1',1,'mc','auto','「주장하는 글」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X01']::text[],false,'{"seq":1,"concept":"K6-1-u5-C1","difficulty":1,"kind":"mc","stem":"「주장하는 글」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"어떤 문제에 대해 다른 사람을 설득할 목적으로 쓰는 글","correct":true},{"t":"본 것을 있는 그대로 전하려고 쓰는 글","mis":"K6-1-u5-X01"},{"t":"그날 있었던 일과 마음을 적어 두는 글","mis":"K6-1-u5-X01"},{"t":"재미있는 일을 꾸며 지어낸 글","mis":"K6-1-u5-X01"}],"explanation":["본 것만 전하는 글이 아니에요.","일기와도 달라요.","다른 사람을 설득하려고 써요."]}'::jsonb),
('g6_1_kor_u5_L01_basic#2','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C2',1,'match','auto','낱말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u5-C2","difficulty":1,"kind":"match","stem":"낱말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"주장","r":"어떤 문제에 대해 내세우는 글쓴이의 의견"},{"l":"이유","r":"그렇게 주장하는 주관적인 까닭"},{"l":"근거","r":"이유를 뒷받침하는 객관적인 자료"}],"mis":"K6-1-u5-X03","explanation":["주장은 의견이에요.","이유는 내 까닭이에요.","근거는 밖에서 가져온 자료예요."]}'::jsonb),
('g6_1_kor_u5_L01_basic#3','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C2',1,'mc','auto','예찬이와 규리의 대화에서 주장에 해당하는 말은 어느 것인가요?',ARRAY['K6-1-u5-X02']::text[],false,'{"seq":3,"concept":"K6-1-u5-C2","difficulty":1,"kind":"mc","stem":"예찬이와 규리의 대화에서 주장에 해당하는 말은 어느 것인가요?","options":[{"t":"반마다 칸을 나누어 쓰면 좋겠어","correct":true},{"t":"신발주머니가 바닥에 쏟아져 있잖아","mis":"K6-1-u5-X02"},{"t":"체육관 사물함이 늘 뒤엉켜 있어","mis":"K6-1-u5-X02"},{"t":"칸이 정해져 있지 않아서 그래","mis":"K6-1-u5-X02"}],"explanation":["본 것을 그대로 말했어요.","문제 상황을 말했어요.","어떻게 하자고 내세운 말이 주장이에요."],"asset":{"type":"speech","turns":[{"who":"예찬","text":"체육관 사물함이 늘 뒤엉켜 있어. 수업이 끝나면 신발주머니가 바닥에 쏟아져 있잖아."},{"who":"규리","text":"칸이 정해져 있지 않아서 그래. 반마다 칸을 나누어 쓰면 좋겠어."},{"who":"예찬","text":"그 생각을 우리끼리만 말하면 바뀌지 않아. 글로 써서 다른 반에도 알리자."},{"who":"규리","text":"그럼 왜 그래야 하는지도 함께 적어야겠다. 그냥 하자고만 하면 아무도 안 들을 테니까."}]}}'::jsonb),
('g6_1_kor_u5_L01_basic#4','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C6',1,'ox','auto','이 단원은 흠 없는 글 한 편을 완성해 내놓는 것이 가장 중요한 시간이에요.',ARRAY['K6-1-u5-X07']::text[],false,'{"seq":4,"concept":"K6-1-u5-C6","difficulty":1,"kind":"ox","stem":"이 단원은 흠 없는 글 한 편을 완성해 내놓는 것이 가장 중요한 시간이에요.","answer":"X","reason_options":[{"t":"쓰고 살펴보고 고치는 글쓰기 과정을 익히는 시간이기 때문에","correct":true},{"t":"좋은 글은 처음부터 흠 없이 써야 하기 때문에","mis":"K6-1-u5-X07"}],"mis":"K6-1-u5-X07","explanation":["완성이 목표가 아니에요.","과정을 살펴보는 단원이에요.","우선 한 줄부터 적어 봐요."]}'::jsonb),
('g6_1_kor_u5_L01_basic#5','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C3',2,'mc','auto','주장하는 글을 쓰면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X05','K6-1-u5-X04','K6-1-u5-X06']::text[],false,'{"seq":5,"concept":"K6-1-u5-C3","difficulty":2,"kind":"mc","stem":"주장하는 글을 쓰면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"왜 그렇게 여기는지 스스로 따져 보게 되어 생각이 정돈된다","correct":true},{"t":"나만 보는 글이라 아무렇게나 써도 된다","mis":"K6-1-u5-X05"},{"t":"이유 없이 주장만 크게 말해도 남이 따른다","mis":"K6-1-u5-X04"},{"t":"글씨를 바르게 쓰는 연습이 된다","mis":"K6-1-u5-X06"}],"explanation":["함께 쓰는 곳을 위한 글이라 책임이 따라요.","주장만으로는 우기는 말이 돼요.","생각이 정돈되고 남을 움직여요."]}'::jsonb),
('g6_1_kor_u5_L01_basic#6','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C4',2,'match','auto','문제 상황과 그때 펼칠 만한 주장을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u5-C4","difficulty":2,"kind":"match","stem":"문제 상황과 그때 펼칠 만한 주장을 알맞게 이으세요.","pairs":[{"l":"체육관 사물함에 칸이 없다","r":"반마다 쓸 칸을 정해 둡시다"},{"l":"빌린 책이 제때 돌아오지 않는다","r":"반납일을 지켜 돌려줍시다"},{"l":"비 오는 날 우산이 복도에 흩어진다","r":"우산은 우산꽂이에 모아 둡시다"}],"mis":"K6-1-u5-X02","explanation":["불편을 먼저 잡아요.","불편을 없앨 방법이 주장이에요.","문제가 다르면 주장도 달라요."]}'::jsonb),
('g6_1_kor_u5_L01_basic#7','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C5',2,'mc','auto','글을 쓰는 과정을 점검하면 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X06']::text[],false,'{"seq":7,"concept":"K6-1-u5-C5","difficulty":2,"kind":"mc","stem":"글을 쓰는 과정을 점검하면 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"보완할 점을 찾아 다시 조정할 수 있다","correct":true},{"t":"글을 몇 줄 썼는지 정확히 셀 수 있다","mis":"K6-1-u5-X06"},{"t":"글을 더 빨리 끝낼 수 있다","mis":"K6-1-u5-X06"},{"t":"글씨가 얼마나 반듯한지 잴 수 있다","mis":"K6-1-u5-X06"}],"explanation":["줄 수를 재는 일이 아니에요.","빠르기를 재는 일도 아니에요.","내 글을 한 걸음 떨어져 보게 돼요."]}'::jsonb),
('g6_1_kor_u5_L01_basic#8','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C2',2,'ox','auto','이유는 있는데 근거가 없으면 글쓴이 혼자만의 생각에 머물러요.',ARRAY['K6-1-u5-X04']::text[],false,'{"seq":8,"concept":"K6-1-u5-C2","difficulty":2,"kind":"ox","stem":"이유는 있는데 근거가 없으면 글쓴이 혼자만의 생각에 머물러요.","answer":"O","reason_options":[{"t":"누구나 확인할 수 있는 자료가 이유를 받쳐 주지 않기 때문에","correct":true},{"t":"이유만 있으면 누구나 그대로 믿기 때문에","mis":"K6-1-u5-X04"}],"mis":"K6-1-u5-X04","explanation":["이유는 내 까닭이에요.","근거가 받쳐 주어야 해요.","셋이 함께 다녀요."]}'::jsonb),
('g6_1_kor_u5_L01_basic#9','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C1',2,'mc','auto','규리가 「왜 그래야 하는지도 함께 적어야겠다」고 말한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X06','K6-1-u5-X01','K6-1-u5-X04']::text[],false,'{"seq":9,"concept":"K6-1-u5-C1","difficulty":2,"kind":"mc","stem":"규리가 「왜 그래야 하는지도 함께 적어야겠다」고 말한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"그냥 하자고만 하면 다른 사람이 따르지 않아 설득하기 어렵기 때문이다","correct":true},{"t":"글을 길게 써야 상을 받을 수 있기 때문이다","mis":"K6-1-u5-X06"},{"t":"본 것을 빠짐없이 전하는 글이기 때문이다","mis":"K6-1-u5-X01"},{"t":"주장만 쓰면 충분하기 때문이다","mis":"K6-1-u5-X04"}],"explanation":["길이를 늘리려는 것이 아니에요.","본 것만 전하는 글이 아니에요.","까닭이 있어야 설득돼요."],"asset":{"type":"speech","turns":[{"who":"예찬","text":"체육관 사물함이 늘 뒤엉켜 있어. 수업이 끝나면 신발주머니가 바닥에 쏟아져 있잖아."},{"who":"규리","text":"칸이 정해져 있지 않아서 그래. 반마다 칸을 나누어 쓰면 좋겠어."},{"who":"예찬","text":"그 생각을 우리끼리만 말하면 바뀌지 않아. 글로 써서 다른 반에도 알리자."},{"who":"규리","text":"그럼 왜 그래야 하는지도 함께 적어야겠다. 그냥 하자고만 하면 아무도 안 들을 테니까."}]}}'::jsonb),
('g6_1_kor_u5_L01_basic#10','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C5',3,'mc','auto','점검하지 않고 끝까지 쓴 뒤에 생기기 쉬운 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X36','K6-1-u5-X06']::text[],false,'{"seq":10,"concept":"K6-1-u5-C5","difficulty":3,"kind":"mc","stem":"점검하지 않고 끝까지 쓴 뒤에 생기기 쉬운 일로 알맞은 것은 어느 것인가요?","options":[{"t":"다 쓰고 나서야 하려던 말이 아니었음을 깨달아 고칠 곳이 한꺼번에 몰린다","correct":true},{"t":"고칠 곳이 하나도 생기지 않는다","mis":"K6-1-u5-X36"},{"t":"글씨가 저절로 반듯해진다","mis":"K6-1-u5-X06"},{"t":"어긋난 부분을 그때그때 바로잡게 된다","mis":"K6-1-u5-X36"}],"explanation":["고칠 곳은 늘 생겨요.","글씨와는 관계없어요.","쓰면서 점검해야 그때그때 바로잡아요."]}'::jsonb),
('g6_1_kor_u5_L01_challenge#1','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C2',2,'mc','auto','대화에서 주장이 아닌 것은 어느 것인가요?',ARRAY['K6-1-u5-X02']::text[],false,'{"seq":1,"concept":"K6-1-u5-C2","difficulty":2,"kind":"mc","stem":"대화에서 주장이 아닌 것은 어느 것인가요?","options":[{"t":"수업이 끝나면 신발주머니가 바닥에 쏟아져 있잖아","correct":true},{"t":"반마다 칸을 나누어 쓰면 좋겠어","mis":"K6-1-u5-X02"},{"t":"글로 써서 다른 반에도 알리자","mis":"K6-1-u5-X02"},{"t":"왜 그래야 하는지도 함께 적자","mis":"K6-1-u5-X02"}],"explanation":["칸을 나누자는 것은 주장이에요.","알리자는 것도 내세운 말이에요.","본 것을 그대로 말한 문장은 문제 상황이에요."],"asset":{"type":"speech","turns":[{"who":"예찬","text":"체육관 사물함이 늘 뒤엉켜 있어. 수업이 끝나면 신발주머니가 바닥에 쏟아져 있잖아."},{"who":"규리","text":"칸이 정해져 있지 않아서 그래. 반마다 칸을 나누어 쓰면 좋겠어."},{"who":"예찬","text":"그 생각을 우리끼리만 말하면 바뀌지 않아. 글로 써서 다른 반에도 알리자."},{"who":"규리","text":"그럼 왜 그래야 하는지도 함께 적어야겠다. 그냥 하자고만 하면 아무도 안 들을 테니까."}]}}'::jsonb),
('g6_1_kor_u5_L01_challenge#2','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C3',2,'ox','auto','주장하는 글은 함께 쓰는 곳을 위한 글이라서 쓰는 사람에게 책임이 따라요.',ARRAY['K6-1-u5-X05']::text[],false,'{"seq":2,"concept":"K6-1-u5-C3","difficulty":2,"kind":"ox","stem":"주장하는 글은 함께 쓰는 곳을 위한 글이라서 쓰는 사람에게 책임이 따라요.","answer":"O","reason_options":[{"t":"여러 사람에게 닿아 생각과 생활을 움직이는 글이기 때문에","correct":true},{"t":"나 혼자만 읽고 덮는 글이기 때문에","mis":"K6-1-u5-X05"}],"mis":"K6-1-u5-X05","explanation":["여러 사람에게 가 닿아요.","나만을 위한 글이 아니에요.","그래서 책임이 따라요."]}'::jsonb),
('g6_1_kor_u5_L01_challenge#3','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C6',3,'error','auto','단원을 시작하며 한 다짐이에요. 알맞지 않은 다짐은 누구의 것인가요?',ARRAY['K6-1-u5-X07']::text[],false,'{"seq":3,"concept":"K6-1-u5-C6","difficulty":3,"kind":"error","stem":"단원을 시작하며 한 다짐이에요. 알맞지 않은 다짐은 누구의 것인가요?","options":[{"t":"예찬 — 「한 번에 흠 없는 글을 써내야 해. 못 쓰면 어떡하지.」","correct":true,"mis_target":"K6-1-u5-X07"},{"t":"규리 — 「우선 한 줄부터 써 놓고 살펴보며 다듬을래.」","mis":"K6-1-u5-X07"},{"t":"슬아 — 「쓰고 살펴보고 고치는 길을 익혀 볼게.」","mis":"K6-1-u5-X07"}],"explanation":["규리는 바르게 다짐했어요.","슬아도 바르게 다짐했어요.","처음부터 완성할 필요는 없어요."]}'::jsonb),
('g6_1_kor_u5_L01_challenge#4','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C4',3,'mc','auto','「급식실 앞에서 줄이 엉켜 서로 밀친다」는 문제에 알맞은 주장은 어느 것인가요?',ARRAY['K6-1-u5-X02','K6-1-u5-X08','K6-1-u5-X27']::text[],false,'{"seq":4,"concept":"K6-1-u5-C4","difficulty":3,"kind":"mc","stem":"「급식실 앞에서 줄이 엉켜 서로 밀친다」는 문제에 알맞은 주장은 어느 것인가요?","options":[{"t":"급식실 앞에서는 한 줄로 섭시다","correct":true},{"t":"급식실 앞이 몹시 북적입니다","mis":"K6-1-u5-X02"},{"t":"반찬을 골고루 먹읍시다","mis":"K6-1-u5-X08"},{"t":"학교 생활을 더 좋게 합시다","mis":"K6-1-u5-X27"}],"explanation":["문제 상황을 다시 말했어요.","줄과 이어지지 않아요.","불편을 없앨 방법이 드러나요."]}'::jsonb),
('g6_1_kor_u5_L01_challenge#5','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C2',3,'mc','auto','「주장만 있고 이유가 없는 말」은 어떤 말이 되나요?',ARRAY['K6-1-u5-X03','K6-1-u5-X01','K6-1-u5-X04']::text[],false,'{"seq":5,"concept":"K6-1-u5-C2","difficulty":3,"kind":"mc","stem":"「주장만 있고 이유가 없는 말」은 어떤 말이 되나요?","options":[{"t":"왜 그래야 하는지 밝히지 않고 우기는 말","correct":true},{"t":"누구나 확인할 수 있는 객관적인 말","mis":"K6-1-u5-X03"},{"t":"본 것을 정확하게 전하는 말","mis":"K6-1-u5-X01"},{"t":"저절로 남을 설득하는 말","mis":"K6-1-u5-X04"}],"explanation":["객관적인 자료는 근거예요.","본 것을 전하는 말과 달라요.","이유가 있어야 설득돼요."]}'::jsonb),
('g6_1_kor_u5_L01_challenge#6','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C5',3,'mc','auto','쓰는 도중에 「이 이유가 주장과 맞나?」를 물어보면 좋아지는 점은 어느 것인가요?',ARRAY['K6-1-u5-X36','K6-1-u5-X06','K6-1-u5-X38']::text[],false,'{"seq":6,"concept":"K6-1-u5-C5","difficulty":3,"kind":"mc","stem":"쓰는 도중에 「이 이유가 주장과 맞나?」를 물어보면 좋아지는 점은 어느 것인가요?","options":[{"t":"어긋난 부분을 그때그때 바로잡을 수 있다","correct":true},{"t":"다 쓰고 나서 한꺼번에 고칠 수 있다","mis":"K6-1-u5-X36"},{"t":"줄 수가 늘어 글이 풍성해진다","mis":"K6-1-u5-X06"},{"t":"이유를 더는 고치지 않아도 된다","mis":"K6-1-u5-X38"}],"explanation":["몰아서 고치면 손대기 어려워요.","줄 수와는 관계없어요.","그때그때 바로잡아요."]}'::jsonb),
('g6_1_kor_u5_L01_challenge#7','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C6',3,'mc','auto','「처음부터 잘 쓴 사람이 아니라 다시 살펴본 사람이 좋은 글에 닿는다」는 말의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X07','K6-1-u5-X38','K6-1-u5-X06']::text[],false,'{"seq":7,"concept":"K6-1-u5-C6","difficulty":3,"kind":"mc","stem":"「처음부터 잘 쓴 사람이 아니라 다시 살펴본 사람이 좋은 글에 닿는다」는 말의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"좋은 글은 써 놓고 살펴보며 고쳐 가는 과정에서 만들어진다","correct":true},{"t":"타고난 사람만 좋은 글을 쓴다","mis":"K6-1-u5-X07"},{"t":"한 번 쓴 글은 고치지 않는 것이 좋다","mis":"K6-1-u5-X38"},{"t":"살펴보는 일은 글씨를 고치는 일이다","mis":"K6-1-u5-X06"}],"explanation":["누구나 고쳐 가며 써요.","고치는 것이 과정이에요.","살펴보는 것은 내용과 짜임이에요."]}'::jsonb),
('g6_1_kor_u5_L01_challenge#8','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C3',4,'mc','auto','「주장하는 글을 쓰다 보면 둘레를 다시 보게 된다」는 말을 가장 잘 보여 주는 것은 어느 것인가요?',ARRAY['K6-1-u5-X05','K6-1-u5-X06','K6-1-u5-X04']::text[],false,'{"seq":8,"concept":"K6-1-u5-C3","difficulty":4,"kind":"mc","stem":"「주장하는 글을 쓰다 보면 둘레를 다시 보게 된다」는 말을 가장 잘 보여 주는 것은 어느 것인가요?","options":[{"t":"사물함 문제를 쓰려고 살피다가 그동안 지나쳤던 체육관 신발장 문제도 눈에 들어왔다","correct":true},{"t":"글을 쓰느라 둘레에 무슨 일이 있는지 신경 쓰지 못했다","mis":"K6-1-u5-X05"},{"t":"글씨를 쓰려고 책상 둘레를 정리했다","mis":"K6-1-u5-X06"},{"t":"주장만 크게 말하자 친구들이 모두 따라왔다","mis":"K6-1-u5-X04"}],"explanation":["오히려 둘레가 보여요.","책상 정리 이야기가 아니에요.","문제를 찾다 보면 지나친 일이 보여요."]}'::jsonb),
('g6_1_kor_u5_L01_challenge#9','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C2',4,'essay','teacher','예찬이와 규리가 쓸 글의 주장을 한 문장으로 쓰고, 이유 하나와 그 이유를 받쳐 줄 근거로 쓸 만한 자료를 하나씩 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u5-C2","difficulty":4,"kind":"essay","stem":"예찬이와 규리가 쓸 글의 주장을 한 문장으로 쓰고, 이유 하나와 그 이유를 받쳐 줄 근거로 쓸 만한 자료를 하나씩 쓰세요.","answer_guide":{"answer":"예: 주장 — 체육관 사물함을 반마다 칸을 나누어 씁시다. 이유 — 칸이 정해지면 신발주머니가 바닥에 쏟아지는 일이 줄기 때문이다. 근거 — 일주일 동안 수업이 끝난 뒤 바닥에 떨어진 신발주머니 수를 세어 적은 기록.","scoring_points":["주장을 할 일이 드러나는 한 문장으로 썼는가","주장과 이어진 이유를 썼는가","누구나 확인할 수 있는 자료를 근거로 들었는가"]},"explanation":["하자는 말로 주장을 세워요.","왜 그런지 이유를 붙여요.","확인할 수 있는 자료를 골라요."],"asset":{"type":"speech","turns":[{"who":"예찬","text":"체육관 사물함이 늘 뒤엉켜 있어. 수업이 끝나면 신발주머니가 바닥에 쏟아져 있잖아."},{"who":"규리","text":"칸이 정해져 있지 않아서 그래. 반마다 칸을 나누어 쓰면 좋겠어."},{"who":"예찬","text":"그 생각을 우리끼리만 말하면 바뀌지 않아. 글로 써서 다른 반에도 알리자."},{"who":"규리","text":"그럼 왜 그래야 하는지도 함께 적어야겠다. 그냥 하자고만 하면 아무도 안 들을 테니까."}]}}'::jsonb),
('g6_1_kor_u5_L01_challenge#10','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C6',4,'essay','teacher','글쓰기를 앞두고 「못 쓰면 어떡하지」 하고 걱정하는 친구에게, 이 단원에서 배우는 것이 무엇인지 알려 주며 해 줄 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u5-C6","difficulty":4,"kind":"essay","stem":"글쓰기를 앞두고 「못 쓰면 어떡하지」 하고 걱정하는 친구에게, 이 단원에서 배우는 것이 무엇인지 알려 주며 해 줄 말을 쓰세요.","answer_guide":{"answer":"예: 이 단원은 처음부터 흠 없는 글을 내는 시간이 아니라 쓰고 살펴보고 고치는 과정을 익히는 시간이야. 처음부터 잘 쓴 사람보다 다시 살펴본 사람이 좋은 글에 닿는대. 그러니 우선 한 줄부터 써 놓고 같이 고쳐 가 보자.","scoring_points":["완성이 아니라 과정을 익히는 단원임을 썼는가","살펴보고 고치는 일의 가치를 썼는가","부담을 덜어 주는 말을 썼는가"]},"explanation":["걱정하는 마음을 떠올려요.","이 단원이 배우는 것을 써요.","해 볼 수 있는 첫걸음을 말해요."]}'::jsonb),
('g6_1_kor_u5_L02_basic#1','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C7',1,'mc','auto','이유와 근거를 바르게 가른 것은 어느 것인가요?',ARRAY['K6-1-u5-X03']::text[],false,'{"seq":1,"concept":"K6-1-u5-C7","difficulty":1,"kind":"mc","stem":"이유와 근거를 바르게 가른 것은 어느 것인가요?","options":[{"t":"이유는 내 생각이고, 근거는 밖에서 가져온 자료이다","correct":true},{"t":"이유는 밖에서 가져온 자료이고, 근거는 내 생각이다","mis":"K6-1-u5-X03"},{"t":"이유와 근거는 같은 말이다","mis":"K6-1-u5-X03"},{"t":"근거는 주장을 다시 한번 말한 것이다","mis":"K6-1-u5-X03"}],"explanation":["거꾸로 말했어요.","둘은 섞지 않아요.","내 까닭과 밖의 자료를 갈라요."]}'::jsonb),
('g6_1_kor_u5_L02_basic#2','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C8',1,'mc','auto','「점심시간 운동장을 나누어 씁시다」에서 근거에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u5-X03','K6-1-u5-X02','K6-1-u5-X09']::text[],false,'{"seq":2,"concept":"K6-1-u5-C8","difficulty":1,"kind":"mc","stem":"「점심시간 운동장을 나누어 씁시다」에서 근거에 해당하는 것은 어느 것인가요?","options":[{"t":"스물다섯 명 가운데 열여덟 명이 부딪힐 뻔했다는 설문 결과","correct":true},{"t":"나누어 쓰면 더 안전하게 놀 수 있기 때문이다","mis":"K6-1-u5-X03"},{"t":"운동장을 학년에 따라 나누어 써야 한다","mis":"K6-1-u5-X02"},{"t":"뒤를 살피느라 멈칫할 일이 줄어든다","mis":"K6-1-u5-X09"}],"explanation":["「때문이다」는 이유예요.","하자는 말은 주장이에요.","출처가 붙은 조사 결과가 근거예요."],"asset":{"type":"passage","lines":["① 점심시간이면 운동장은 공놀이와 달리기와 줄넘기가 한꺼번에 벌어져","서로 부딪힐까 봐 마음을 놓지 못한다. 점심시간 운동장을 학년에 따라","나누어 써야 한다. 지금부터 그렇게 해야 하는 까닭을 살펴보자.","② 첫째, 나누어 쓰면 더 안전하게 놀 수 있기 때문이다. 우리 반 스물다섯","명 가운데 열여덟 명이 다른 사람과 부딪힐 뻔한 적이 있다고 답했다.","(솔바람반(2026), 「점심시간 운동장 이용 설문」, 학급 게시판.)","넉넉한 곳에서 놀면 뒤를 살피느라 멈칫할 일이 줄어든다."],"title":"「점심시간 운동장을 나누어 씁시다」 — 앞부분"}}'::jsonb),
('g6_1_kor_u5_L02_basic#3','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C11',1,'ox','auto','서론에서는 문제를 제기하고 주장을 밝혀요.',ARRAY['K6-1-u5-X10']::text[],false,'{"seq":3,"concept":"K6-1-u5-C11","difficulty":1,"kind":"ox","stem":"서론에서는 문제를 제기하고 주장을 밝혀요.","answer":"O","reason_options":[{"t":"왜 이 글을 쓰게 되었는지와 글쓴이의 의견을 먼저 드러내는 부분이기 때문에","correct":true},{"t":"이유와 근거를 모두 늘어놓는 부분이기 때문에","mis":"K6-1-u5-X10"}],"mis":"K6-1-u5-X10","explanation":["서론은 글의 앞부분이에요.","문제와 주장을 먼저 밝혀요.","이유와 근거는 본론에서 펼쳐요."]}'::jsonb),
('g6_1_kor_u5_L02_basic#4','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C12',1,'match','auto','글의 부분과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K6-1-u5-C12","difficulty":1,"kind":"match","stem":"글의 부분과 하는 일을 알맞게 이으세요.","pairs":[{"l":"서론","r":"문제를 제기하고 주장을 밝힌다"},{"l":"본론","r":"이유와 근거로 주장을 펼친다"},{"l":"결론","r":"요약하고 다시 한번 강조한다"}],"mis":"K6-1-u5-X10","explanation":["서론은 꺼내요.","본론은 펼쳐요.","결론은 모아요."]}'::jsonb),
('g6_1_kor_u5_L02_basic#5','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C9',2,'mc','auto','「운동장을 나누어 쓰자」는 주장과 관련이 없는 이유는 어느 것인가요?',ARRAY['K6-1-u5-X08']::text[],false,'{"seq":5,"concept":"K6-1-u5-C9","difficulty":2,"kind":"mc","stem":"「운동장을 나누어 쓰자」는 주장과 관련이 없는 이유는 어느 것인가요?","options":[{"t":"급식을 남기면 아깝기 때문이다","correct":true},{"t":"더 안전하게 놀 수 있기 때문이다","mis":"K6-1-u5-X08"},{"t":"놀 곳을 두고 벌어지는 다툼이 줄어들기 때문이다","mis":"K6-1-u5-X08"},{"t":"하려던 놀이를 끝까지 할 수 있기 때문이다","mis":"K6-1-u5-X08"}],"explanation":["안전은 운동장과 이어져요.","다툼도 이어져요.","급식은 운동장을 나누는 일과 이어지지 않아요."]}'::jsonb),
('g6_1_kor_u5_L02_basic#6','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C14',2,'mc','auto','②문단의 중심 문장은 어느 것인가요?',ARRAY['K6-1-u5-X13','K6-1-u5-X10']::text[],false,'{"seq":6,"concept":"K6-1-u5-C14","difficulty":2,"kind":"mc","stem":"②문단의 중심 문장은 어느 것인가요?","options":[{"t":"첫째, 나누어 쓰면 더 안전하게 놀 수 있기 때문이다","correct":true},{"t":"스물다섯 명 가운데 열여덟 명이 부딪힐 뻔한 적이 있다고 답했다","mis":"K6-1-u5-X13"},{"t":"넉넉한 곳에서 놀면 뒤를 살피느라 멈칫할 일이 줄어든다","mis":"K6-1-u5-X13"},{"t":"점심시간 운동장을 학년에 따라 나누어 써야 한다","mis":"K6-1-u5-X10"}],"explanation":["수가 든 문장은 받쳐 주는 쪽이에요.","이 문장도 뒷받침 문장이에요.","문단 전체를 한 문장으로 줄여요."],"asset":{"type":"passage","lines":["① 점심시간이면 운동장은 공놀이와 달리기와 줄넘기가 한꺼번에 벌어져","서로 부딪힐까 봐 마음을 놓지 못한다. 점심시간 운동장을 학년에 따라","나누어 써야 한다. 지금부터 그렇게 해야 하는 까닭을 살펴보자.","② 첫째, 나누어 쓰면 더 안전하게 놀 수 있기 때문이다. 우리 반 스물다섯","명 가운데 열여덟 명이 다른 사람과 부딪힐 뻔한 적이 있다고 답했다.","(솔바람반(2026), 「점심시간 운동장 이용 설문」, 학급 게시판.)","넉넉한 곳에서 놀면 뒤를 살피느라 멈칫할 일이 줄어든다."],"title":"「점심시간 운동장을 나누어 씁시다」 — 앞부분"}}'::jsonb),
('g6_1_kor_u5_L02_basic#7','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C12',2,'ox','auto','본론에서 하나의 이유에는 근거가 꼭 하나만 붙어야 해요.',ARRAY['K6-1-u5-X12']::text[],false,'{"seq":7,"concept":"K6-1-u5-C12","difficulty":2,"kind":"ox","stem":"본론에서 하나의 이유에는 근거가 꼭 하나만 붙어야 해요.","answer":"X","reason_options":[{"t":"하나의 이유에 근거가 여러 개 붙기도 하기 때문에","correct":true},{"t":"근거가 둘이면 이유가 흐려지기 때문에","mis":"K6-1-u5-X12"}],"mis":"K6-1-u5-X12","explanation":["근거 수는 정해져 있지 않아요.","여러 근거가 받치기도 해요.","이유와 이어지는지가 중요해요."]}'::jsonb),
('g6_1_kor_u5_L02_basic#8','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C13',2,'mc','auto','⑤문단이 결론인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X11','K6-1-u5-X10']::text[],false,'{"seq":8,"concept":"K6-1-u5-C13","difficulty":2,"kind":"mc","stem":"⑤문단이 결론인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"세 가지 까닭을 모아 말하고 주장을 다시 강조했기 때문이다","correct":true},{"t":"처음 꺼내는 새 근거를 내놓았기 때문이다","mis":"K6-1-u5-X11"},{"t":"문제를 처음으로 제기했기 때문이다","mis":"K6-1-u5-X10"},{"t":"설문 결과를 자세히 밝혔기 때문이다","mis":"K6-1-u5-X10"}],"explanation":["결론은 새 근거를 꺼내지 않아요.","문제 제기는 서론이에요.","모으고 다시 힘주는 부분이에요."],"asset":{"type":"passage","lines":["③ 둘째, 하려던 놀이를 끝까지 할 수 있기 때문이다. 사흘 동안 세어 보니","줄넘기를 하다 공에 밀려 그만둔 무리가 하루 평균 네 무리였다.","(솔바람반(2026), 「사흘 동안의 운동장 관찰 기록」, 학급 게시판.)","④ 셋째, 다툼이 줄어들기 때문이다. 학년 선생님께 여쭈어 보니 점심시간","다툼 가운데 놀 곳을 두고 벌어지는 다툼이 가장 잦다고 하셨다.","(김○○ 선생님 면담(2026), 「점심시간 생활 지도」, 육 학년 교무실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 요일마다 학년을 정하는 방법도","있다. 모두에게 넉넉한 점심시간이 되도록 운동장을 나누어 쓰자."],"title":"「점심시간 운동장을 나누어 씁시다」 — 뒷부분"}}'::jsonb),
