('g6_1_kor_u6_review_a#9','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C7',2,'mc','auto','담희 글의 주장은 무엇인가요?',ARRAY['K6-1-u6-X11','K6-1-u6-X07']::text[],false,'{"seq":9,"concept":"K6-1-u6-C7","difficulty":2,"kind":"mc","stem":"담희 글의 주장은 무엇인가요?","options":[{"t":"쉬는 시간마다 창문을 열어 두자","correct":true},{"t":"창문을 닫아 두자","mis":"K6-1-u6-X11"},{"t":"감기에 걸리지 않게 하자","mis":"K6-1-u6-X07"},{"t":"셋째 시간을 줄이자","mis":"K6-1-u6-X07"}],"explanation":["주장과 반대예요.","이유에 나온 말이에요.","서론과 결론이 함께 가리켜요. (바로잡기: 창문을 열어도 감기에 걸릴 수 있어요.) (바로잡기: 창문을 열어도 해결 안 되는 문제가 있어요.)"],"asset":{"type":"passage","lines":["④ 셋째, 창문을 열어 두면 감기에 걸리지 않습니다.","옆 반 친구가 그렇게 말해 주었습니다.","⑤ 창문만 열면 교실의 모든 문제가 사라집니다.","⑥ 추운 날에는 잠깐만 열어도 됩니다. 쉬는 시간마다 창문을 열어 둡시다."],"title":"담희의 글 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb),
('g6_1_kor_u6_review_a#10','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C12',2,'mc','auto','담희 글에서 근거로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X19','K6-1-u6-X26','K6-1-u6-X16']::text[],false,'{"seq":10,"concept":"K6-1-u6-C12","difficulty":2,"kind":"mc","stem":"담희 글에서 근거로 알맞은 것은 어느 것인가요?","options":[{"t":"일주일 동안 창문을 열어 보니 「답답하다」고 적은 친구가 날마다 줄었다","correct":true},{"t":"옆 반 친구가 감기에 안 걸린다고 말해 주었다","mis":"K6-1-u6-X19"},{"t":"창문만 열면 모든 문제가 사라진다","mis":"K6-1-u6-X26"},{"t":"추운 날에는 잠깐만 열어도 된다","mis":"K6-1-u6-X16"}],"explanation":["전해 들은 말이에요.","부풀린 말이에요.","직접 해 보고 적은 기록이에요."],"asset":{"type":"passage","lines":["① 셋째 시간이 끝날 무렵이면 교실 공기가 답답해집니다.","쉬는 시간마다 창문을 열어 두면 좋겠습니다.","② 첫째, 바깥 공기가 들어와 교실 공기가 바뀝니다. 우리 반이 일주일 동안","쉬는 시간마다 창문을 열어 보니, 「답답하다」고 적은 친구가 날마다 줄었습니다.","③ 둘째, 창문을 닫아 두면 바깥 소리가 들어오지 않아 수업에 마음을 모을 수 있습니다."],"title":"담희의 글 「쉬는 시간마다 창문을 열어 둡시다」 — 앞부분 (흠을 일부러 넣은 글)"}}'::jsonb),
