('g6_1_kor_u6_review_a#15','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C42',2,'mc','auto','도율이의 초안에서 고치지 않아도 되는 문구는 어느 것인가요?',ARRAY['K6-1-u6-X26']::text[],false,'{"seq":15,"concept":"K6-1-u6-C42","difficulty":2,"kind":"mc","stem":"도율이의 초안에서 고치지 않아도 되는 문구는 어느 것인가요?","options":[{"t":"ㄹ. 잠가요, 비누칠하는 동안","correct":true},{"t":"ㄱ. 물을 틀어 두면 지구의 물이 하루 만에 말라 버립니다!","mis":"K6-1-u6-X26"},{"t":"ㄴ. 이 광고만 보면 물 낭비가 모두 사라집니다.","mis":"K6-1-u6-X26"},{"t":"ㄷ. 비누칠할 때 물을 틀어 두면 무조건 벌금!","mis":"K6-1-u6-X26"}],"explanation":["사실이 아니에요 — 지구의 물이 하루 만에 마르지 않아요.","부풀렸어요.","뜻이 분명하고 부풀리지 않았어요 — ㄷ도 없는 벌금 규칙을 있다고 한 거짓이에요."],"asset":{"type":"passage","lines":["장면 — 비누 거품이 묻은 손 아래로 물이 콸콸 흐르는 그림","ㄱ. 물을 틀어 두면 지구의 물이 하루 만에 말라 버립니다!","ㄴ. 이 광고만 보면 물 낭비가 모두 사라집니다.","ㄷ. 비누칠할 때 물을 틀어 두면 무조건 벌금!","ㄹ. 잠가요, 비누칠하는 동안"],"title":"도율의 공익 광고 초안 (흠을 일부러 넣은 글)"}}'::jsonb),
('g6_1_kor_u6_review_a#16','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C21',2,'mc','auto','도율이의 첫 말 「이 글은 다 버리는 게 낫겠다」에 대한 판단으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X21','K6-1-u6-X01','K6-1-u6-X05']::text[],false,'{"seq":16,"concept":"K6-1-u6-C21","difficulty":2,"kind":"mc","stem":"도율이의 첫 말 「이 글은 다 버리는 게 낫겠다」에 대한 판단으로 알맞은 것은 어느 것인가요?","options":[{"t":"걸린 곳만 짚고 주장과 직접 센 기록은 받아들여야 한다","correct":true},{"t":"걸린 곳이 셋이니 버리는 게 맞다","mis":"K6-1-u6-X21"},{"t":"걸린 곳이 있어도 모두 받아들여야 한다","mis":"K6-1-u6-X01"},{"t":"더 많은 흠을 찾아야 한다","mis":"K6-1-u6-X05"}],"explanation":["쓸 것까지 버려요.","걸린 곳은 짚어요.","받아들일 것과 물릴 것을 나눠요."],"asset":{"type":"speech","turns":[{"who":"도율","text":"담희 글에 이상한 데가 세 군데나 있어. 이 글은 다 버리는 게 낫겠다."},{"who":"담희","text":"걸린 곳만 짚어 줘. 창문을 열자는 주장과 직접 센 기록도 틀렸어?"},{"who":"도율","text":"그건 아니야. 그리고 ⑤문단은 그냥 별로야."},{"who":"담희","text":"별로라고만 하면 어디를 고칠지 모르겠어. 왜 걸리는지 까닭을 말해 줄래?"}]}}'::jsonb),
('g6_1_kor_u6_review_a#17','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C20',3,'mc','auto','담희 글을 차례대로 잰 결과로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X21','K6-1-u6-X10','K6-1-u6-X19']::text[],false,'{"seq":17,"concept":"K6-1-u6-C20","difficulty":3,"kind":"mc","stem":"담희 글을 차례대로 잰 결과로 알맞은 것은 어느 것인가요?","options":[{"t":"주장은 가치 있음 → 이유 ③은 어긋나고 ④는 사실이 아님 → 근거 ④는 전해 들은 말이라 걸림","correct":true},{"t":"근거가 하나 걸렸으니 주장도 가치 없음","mis":"K6-1-u6-X21"},{"t":"이유 ③은 맞는 말이니 뒷받침함","mis":"K6-1-u6-X10"},{"t":"전해 들은 말도 누가 말했는지 있으니 알맞음","mis":"K6-1-u6-X19"}],"explanation":["주장의 가치는 따로 재요.","맞는 말이어도 어긋나요.","주장 → 이유 → 근거 차례로 쟀어요."]}'::jsonb),
('g6_1_kor_u6_review_a#18','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C37',3,'mc','auto','「공부가 저절로 되는 형광펜!」을 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u6-X35','K6-1-u6-X26']::text[],false,'{"seq":18,"concept":"K6-1-u6-C37","difficulty":3,"kind":"mc","stem":"「공부가 저절로 되는 형광펜!」을 알맞게 고친 것은 어느 것인가요?","options":[{"t":"중요한 곳을 눈에 띄게 표시해 주는 형광펜","correct":true},{"t":"공부가 정말 저절로 되는 형광펜","mis":"K6-1-u6-X35"},{"t":"세상 모든 공부를 대신하는 형광펜","mis":"K6-1-u6-X26"},{"t":"형광펜을 쓰지 맙시다","mis":"K6-1-u6-X35"}],"explanation":["거짓을 그대로 두었어요.","더 부풀렸어요.","형광펜이 실제로 하는 일만 말했어요."],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb),
('g6_1_kor_u6_review_a#19','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C37',3,'mc','auto','「갯벌은 언제든 걸어 들어가 놀아도 좋습니다」를 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u6-X35','K6-1-u6-X33']::text[],false,'{"seq":19,"concept":"K6-1-u6-C37","difficulty":3,"kind":"mc","stem":"「갯벌은 언제든 걸어 들어가 놀아도 좋습니다」를 알맞게 고친 것은 어느 것인가요?","options":[{"t":"갯벌에 들어갈 때에는 바닷물이 들어오는 때를 확인하고 어른과 함께 가야 합니다","correct":true},{"t":"갯벌은 언제든 정말 놀아도 좋습니다","mis":"K6-1-u6-X35"},{"t":"갯벌에는 절대 들어가지 맙시다","mis":"K6-1-u6-X35"},{"t":"갯벌은 언제나 안전합니다","mis":"K6-1-u6-X33"}],"explanation":["감춘 것을 밝히지 않았어요.","뜻까지 바꿨어요.","알아야 할 것을 밝혔어요."],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb),
('g6_1_kor_u6_review_a#20','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C42',3,'mc','auto','「이 광고만 보면 물 낭비가 모두 사라집니다」를 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u6-X35','K6-1-u6-X26']::text[],false,'{"seq":20,"concept":"K6-1-u6-C42","difficulty":3,"kind":"mc","stem":"「이 광고만 보면 물 낭비가 모두 사라집니다」를 알맞게 고친 것은 어느 것인가요?","options":[{"t":"한 사람이 잠그면 한 컵만큼 물이 남습니다","correct":true},{"t":"이 광고만 보면 물 낭비가 정말 다 사라집니다","mis":"K6-1-u6-X35"},{"t":"물 낭비는 영원히 사라집니다","mis":"K6-1-u6-X26"},{"t":"물을 아예 쓰지 맙시다","mis":"K6-1-u6-X35"}],"explanation":["부풀린 그대로예요.","더 부풀렸어요.","뜻은 살리고 크기만 줄였어요."],"asset":{"type":"passage","lines":["장면 — 비누 거품이 묻은 손 아래로 물이 콸콸 흐르는 그림","ㄱ. 물을 틀어 두면 지구의 물이 하루 만에 말라 버립니다!","ㄴ. 이 광고만 보면 물 낭비가 모두 사라집니다.","ㄷ. 비누칠할 때 물을 틀어 두면 무조건 벌금!","ㄹ. 잠가요, 비누칠하는 동안"],"title":"도율의 공익 광고 초안 (흠을 일부러 넣은 글)"}}'::jsonb),
('g6_1_kor_u6_review_a#21','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C47',3,'mc','auto','「그늘막을 더 세웁시다」에 두 자를 모두 댄 판단은 어느 것인가요?',ARRAY['K6-1-u6-X46','K6-1-u6-X21']::text[],false,'{"seq":21,"concept":"K6-1-u6-C47","difficulty":3,"kind":"mc","stem":"「그늘막을 더 세웁시다」에 두 자를 모두 댄 판단은 어느 것인가요?","options":[{"t":"내용: 문단 ④가 주장과 어긋남 · 표현: 문단 ⑤가 과장과 거짓","correct":true},{"t":"내용: 문단 ④가 어긋남 — 표현은 보지 않음","mis":"K6-1-u6-X46"},{"t":"표현: 문단 ⑤가 과장 — 내용은 보지 않음","mis":"K6-1-u6-X46"},{"t":"걸린 곳이 있으니 모두 버림","mis":"K6-1-u6-X21"}],"explanation":["표현도 봐야 해요.","내용도 봐야 해요.","여섯 물음을 다 댔어요 — ⑤는 「볕을 가려 조금 덜 덥다」로 바로잡아요. (바로잡기: 그늘막 아래도 더울 수 있어요.)"],"asset":{"type":"passage","lines":["④ 셋째, 그늘막 아래에서는 친구들과 이야기를 나눌 수 있어 즐겁습니다.","⑤ 그늘막 하나면 여름 더위가 모두 사라집니다. 그늘막 아래에서는 절대 덥지 않습니다.","⑥ 그늘막은 세우는 데 오래 걸리지 않습니다.","여름이 오기 전에 건널목 앞에 그늘막을 더 세웁시다."],"title":"「그늘막을 더 세웁시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb),
('g6_1_kor_u6_review_a#22','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C48',3,'mc','auto','낱말을 바르게 쓴 문장은 어느 것인가요?',ARRAY['K6-1-u6-X47']::text[],false,'{"seq":22,"concept":"K6-1-u6-C48","difficulty":3,"kind":"mc","stem":"낱말을 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"고양이가 마당의 참새를 쫓았다.","correct":true},{"t":"꿈을 쫓아 열심히 공부했다.","mis":"K6-1-u6-X47"},{"t":"수수께끼의 답을 맞추었다.","mis":"K6-1-u6-X47"},{"t":"모둠 수를 하나 늘였다.","mis":"K6-1-u6-X47"}],"explanation":["목표를 따르면 「좇다」예요.","답을 옳게 대면 「맞히다」예요.","수를 많게 하면 「늘리다」예요 — 몰아내거나 뒤를 따르면 「쫓다」예요."]}'::jsonb),
('g6_1_kor_u6_review_a#23','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C47',4,'mc','auto','담희 글 전체를 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u6-X21','K6-1-u6-X01','K6-1-u6-X46']::text[],false,'{"seq":23,"concept":"K6-1-u6-C47","difficulty":4,"kind":"mc","stem":"담희 글 전체를 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"주장과 문단 ②의 이유 · 기록은 받아들일 만하지만, 어긋난 이유 ③ · 사실이 아닌 이유와 전해 들은 근거 ④ · 과장 ⑤를 고쳐야 한다","correct":true},{"t":"걸린 곳이 많으니 버리고 새로 써야 한다","mis":"K6-1-u6-X21"},{"t":"주장이 좋으니 고칠 곳이 없다","mis":"K6-1-u6-X01"},{"t":"표현만 고치면 된다","mis":"K6-1-u6-X46"}],"explanation":["버리지 않고 고쳐요.","걸린 곳이 있어요.","내용도 걸린 곳이 있어요."],"asset":{"type":"passage","lines":["④ 셋째, 창문을 열어 두면 감기에 걸리지 않습니다.","옆 반 친구가 그렇게 말해 주었습니다.","⑤ 창문만 열면 교실의 모든 문제가 사라집니다.","⑥ 추운 날에는 잠깐만 열어도 됩니다. 쉬는 시간마다 창문을 열어 둡시다."],"title":"담희의 글 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb),
('g6_1_kor_u6_review_a#24','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C18',4,'essay','teacher','담희 글에서 내용이 걸리는 곳 두 군데를 찾아 까닭을 쓰고, 그중 하나를 주장 편에 서도록 고쳐 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u6-C18","difficulty":4,"kind":"essay","stem":"담희 글에서 내용이 걸리는 곳 두 군데를 찾아 까닭을 쓰고, 그중 하나를 주장 편에 서도록 고쳐 쓰세요.","answer_guide":{"answer":"예: 문단 ③ 「창문을 닫아 두면 바깥 소리가 들어오지 않아 수업에 마음을 모을 수 있다」는 닫자는 쪽을 가리켜 열어 두자는 주장과 어긋난다. 문단 ④ 「창문을 열어 두면 감기에 걸리지 않는다」는 사실이 아니고, 옆 반 친구의 말은 전해 들은 말이라 확인할 수 없다. 문단 ③을 고치면 — 「둘째, 바깥 공기를 들이면 머리가 맑아진 느낌이 들어 다음 시간을 더 상쾌하게 시작할 수 있습니다.」","scoring_points":["걸리는 곳 두 군데를 찾았는가","각각 까닭을 썼는가","하나를 주장 편으로 고쳐 썼는가"]},"explanation":["세 기준을 차례로 대요.","까닭을 붙여요.","같은 문제를 주장 쪽으로 이어요."],"asset":{"type":"passage","lines":["④ 셋째, 창문을 열어 두면 감기에 걸리지 않습니다.","옆 반 친구가 그렇게 말해 주었습니다.","⑤ 창문만 열면 교실의 모든 문제가 사라집니다.","⑥ 추운 날에는 잠깐만 열어도 됩니다. 쉬는 시간마다 창문을 열어 둡시다."],"title":"담희의 글 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb),
('g6_1_kor_u6_review_a#25','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C47',4,'essay','teacher','이 단원이 남긴 여섯 물음을 쓰고, 그 물음을 쓸 때 꼭 함께 해야 할 일 한 가지를 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u6-C47","difficulty":4,"kind":"essay","stem":"이 단원이 남긴 여섯 물음을 쓰고, 그 물음을 쓸 때 꼭 함께 해야 할 일 한 가지를 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 내용의 타당성 — 주장은 가치 있고 중요한가, 이유는 주장을 뒷받침하는가, 근거는 이유를 뒷받침하는가. 표현의 적절성 — 거짓된 표현이 있는가, 과장된 표현이 있는가, 감추는 내용이 있는가. 이 물음을 쓸 때에는 그렇게 판단한 까닭을 함께 대야 한다. 까닭 없는 판단은 기분일 뿐이라 다른 사람이 따져 볼 수 없기 때문이다.","scoring_points":["내용의 타당성 세 물음을 썼는가","표현의 적절성 세 물음을 썼는가","까닭을 함께 대야 함을 썼는가"]},"explanation":["두 자를 떠올려요.","여섯 물음을 써요.","까닭과 이어 정리해요."]}'::jsonb),
('g6_1_kor_u6_review_b#1','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C3',1,'mc','auto','판단하며 읽기의 두 갈래로 알맞게 묶은 것은 어느 것인가요?',ARRAY['K6-1-u6-X23','K6-1-u6-X03','K6-1-u6-X07']::text[],false,'{"seq":1,"concept":"K6-1-u6-C3","difficulty":1,"kind":"mc","stem":"판단하며 읽기의 두 갈래로 알맞게 묶은 것은 어느 것인가요?","options":[{"t":"내용의 타당성 · 표현의 적절성","correct":true},{"t":"글의 길이 · 글씨의 크기","mis":"K6-1-u6-X23"},{"t":"제목 · 그림","mis":"K6-1-u6-X03"},{"t":"서론 · 결론","mis":"K6-1-u6-X07"}],"explanation":["길이와 크기는 갈래가 아니에요.","제목과 그림만이 아니에요.","무엇을 · 어떻게 말하는가예요."]}'::jsonb),
