('g6_1_kor_u6_review_b#9','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C11',2,'mc','auto','담희 글에서 주장과 어긋나는 이유는 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X07']::text[],false,'{"seq":9,"concept":"K6-1-u6-C11","difficulty":2,"kind":"mc","stem":"담희 글에서 주장과 어긋나는 이유는 어느 것인가요?","options":[{"t":"창문을 닫아 두면 바깥 소리가 들어오지 않아 수업에 마음을 모을 수 있다","correct":true},{"t":"바깥 공기가 들어와 교실 공기가 바뀐다","mis":"K6-1-u6-X05"},{"t":"셋째 시간이 끝날 무렵 교실 공기가 답답해진다","mis":"K6-1-u6-X07"},{"t":"추운 날에는 잠깐만 열어도 된다","mis":"K6-1-u6-X05"}],"explanation":["주장과 이어지는 이유예요.","문제를 꺼낸 서론이에요.","닫자는 쪽을 가리켜 어긋나요 — 열자는 주장 편으로 고쳐야 해요."],"asset":{"type":"passage","lines":["① 셋째 시간이 끝날 무렵이면 교실 공기가 답답해집니다.","쉬는 시간마다 창문을 열어 두면 좋겠습니다.","② 첫째, 바깥 공기가 들어와 교실 공기가 바뀝니다. 우리 반이 일주일 동안","쉬는 시간마다 창문을 열어 보니, 「답답하다」고 적은 친구가 날마다 줄었습니다.","③ 둘째, 창문을 닫아 두면 바깥 소리가 들어오지 않아 수업에 마음을 모을 수 있습니다."],"title":"담희의 글 「쉬는 시간마다 창문을 열어 둡시다」 — 앞부분 (흠을 일부러 넣은 글)"}}'::jsonb),
('g6_1_kor_u6_review_b#10','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C19',2,'mc','auto','「옆 반 친구가 그렇게 말해 주었습니다」가 근거로 알맞지 않은 까닭은 어느 것인가요?',ARRAY['K6-1-u6-X19','K6-1-u6-X08']::text[],false,'{"seq":10,"concept":"K6-1-u6-C19","difficulty":2,"kind":"mc","stem":"「옆 반 친구가 그렇게 말해 주었습니다」가 근거로 알맞지 않은 까닭은 어느 것인가요?","options":[{"t":"한 사람에게서 전해 들은 말이라 누구도 다시 확인할 수 없기 때문이다","correct":true},{"t":"옆 반 친구는 어리기 때문이다","mis":"K6-1-u6-X19"},{"t":"근거가 너무 길기 때문이다","mis":"K6-1-u6-X08"},{"t":"친구 이름을 밝히지 않았기 때문이다","mis":"K6-1-u6-X19"}],"explanation":["나이 문제가 아니에요.","길이 문제가 아니에요.","이름을 밝혀도 전해 들은 말이에요 — 확인할 수 있는 근거로 바꿔요. (바로잡기: 창문을 열어도 감기에 걸릴 수 있어요.) (바로잡기: 창문을 열어도 해결 안 되는 문제가 있어요.)"],"asset":{"type":"passage","lines":["④ 셋째, 창문을 열어 두면 감기에 걸리지 않습니다.","옆 반 친구가 그렇게 말해 주었습니다.","⑤ 창문만 열면 교실의 모든 문제가 사라집니다.","⑥ 추운 날에는 잠깐만 열어도 됩니다. 쉬는 시간마다 창문을 열어 둡시다."],"title":"담희의 글 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb),
('g6_1_kor_u6_review_b#11','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C26',2,'mc','auto','「영원히 마르지 않는 잉크!」가 걸리는 기준과 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X25','K6-1-u6-X17','K6-1-u6-X27']::text[],false,'{"seq":11,"concept":"K6-1-u6-C26","difficulty":2,"kind":"mc","stem":"「영원히 마르지 않는 잉크!」가 걸리는 기준과 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"과장 — 잘 마르지 않게 만든 것은 맞지만 어떤 경우에도 그렇다고 부풀렸다","correct":true},{"t":"거짓 — 잉크가 아예 없다","mis":"K6-1-u6-X25"},{"t":"알맞음 — 광고에 적혀 있다","mis":"K6-1-u6-X17"},{"t":"감춤 — 색을 밝히지 않았다","mis":"K6-1-u6-X27"}],"explanation":["기능은 있어요.","적혀 있다는 건 까닭이 아니에요.","있는 기능을 부풀렸어요 — 작은 글씨가 마를 수 있다고 밝혀요. (바로잡기: 형광펜에는 공부를 대신해 주는 기능이 없어요.)"],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb),
('g6_1_kor_u6_review_b#12','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C24',2,'mc','auto','형광펜 광고가 「※ 뚜껑을 열어 두면 금방 마를 수 있음」을 아주 작게 적은 것을 바르게 판단한 것은 어느 것인가요?',ARRAY['K6-1-u6-X15','K6-1-u6-X27','K6-1-u6-X24']::text[],false,'{"seq":12,"concept":"K6-1-u6-C24","difficulty":2,"kind":"mc","stem":"형광펜 광고가 「※ 뚜껑을 열어 두면 금방 마를 수 있음」을 아주 작게 적은 것을 바르게 판단한 것은 어느 것인가요?","options":[{"t":"꼭 알아야 할 조건을 눈에 들어오지 않게 적어, 「영원히 마르지 않는」과 함께 보면 감추는 내용에 가깝다","correct":true},{"t":"작은 글씨는 안 읽어도 된다","mis":"K6-1-u6-X15"},{"t":"적었으니 아무 문제가 없다","mis":"K6-1-u6-X27"},{"t":"실수로 작게 썼을 뿐이다","mis":"K6-1-u6-X24"}],"explanation":["조건이 거기 있어요.","읽을 수 있는 크기여야 해요.","작게 쓴 것도 뜻이 있어요."],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb),
('g6_1_kor_u6_review_b#13','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C35',2,'mc','auto','갯벌 글에서 과장된 표현은 어느 것인가요?',ARRAY['K6-1-u6-X28','K6-1-u6-X05']::text[],false,'{"seq":13,"concept":"K6-1-u6-C35","difficulty":2,"kind":"mc","stem":"갯벌 글에서 과장된 표현은 어느 것인가요?","options":[{"t":"갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다","correct":true},{"t":"갯벌은 언제든 걸어 들어가 놀아도 좋습니다","mis":"K6-1-u6-X28"},{"t":"갯벌을 보면 살림터를 알 수 있습니다","mis":"K6-1-u6-X05"},{"t":"갯벌 생물이 바닷물을 깨끗하게 하는 데 도움을 줍니다","mis":"K6-1-u6-X05"}],"explanation":["이건 감추는 내용이에요.","글쓴이의 정리예요.","지나치게 잡으면 줄어들어요 — 바르게는 「알맞게 잡으면 다시 늘어날 수 있습니다」예요. (바로잡기: 우리나라에는 모래 바닷가 · 바위 바닷가도 있어요.) (바로잡기: 바닷물이 들어오는 때에는 갯벌에 들어가면 위험해요.)"],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb),
('g6_1_kor_u6_review_b#14','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C38',2,'mc','auto','갯벌 글을 읽고 다른 관점에서 세울 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X36','K6-1-u6-X31']::text[],false,'{"seq":14,"concept":"K6-1-u6-C38","difficulty":2,"kind":"mc","stem":"갯벌 글을 읽고 다른 관점에서 세울 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"「갯벌이 줄어들면 어떤 일이 생길까?」","correct":true},{"t":"「갯벌은 왜 이렇게 좋을까?」","mis":"K6-1-u6-X36"},{"t":"「이 글만 읽으면 충분하겠지?」","mis":"K6-1-u6-X36"},{"t":"「이 글을 다 외웠을까?」","mis":"K6-1-u6-X31"}],"explanation":["같은 쪽의 물음이에요.","한 편만 읽고 끝내지 않아요.","다른 쪽에서 물었어요 — 관련 글을 더 찾아 읽어요."]}'::jsonb),
('g6_1_kor_u6_review_b#15','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C40',2,'mc','auto','도율이가 초안을 스스로 검사할 때 쓸 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X23','K6-1-u6-X42','K6-1-u6-X38']::text[],false,'{"seq":15,"concept":"K6-1-u6-C40","difficulty":2,"kind":"mc","stem":"도율이가 초안을 스스로 검사할 때 쓸 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"「없는 것을 있다고 했는가 · 부풀렸는가 · 감추었는가?」","correct":true},{"t":"「글씨가 예쁜가?」","mis":"K6-1-u6-X23"},{"t":"「남의 광고보다 센가?」","mis":"K6-1-u6-X42"},{"t":"「내 광고니까 괜찮은가?」","mis":"K6-1-u6-X38"}],"explanation":["겉모습이 아니에요.","세기를 겨루지 않아요.","읽을 때의 자를 만들 때도 써요."]}'::jsonb),
('g6_1_kor_u6_review_b#16','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C6',2,'mc','auto','담희가 도율이에게 「까닭을 말해 줄래?」라고 한 까닭은 어느 것인가요?',ARRAY['K6-1-u6-X45','K6-1-u6-X06','K6-1-u6-X21']::text[],false,'{"seq":16,"concept":"K6-1-u6-C6","difficulty":2,"kind":"mc","stem":"담희가 도율이에게 「까닭을 말해 줄래?」라고 한 까닭은 어느 것인가요?","options":[{"t":"까닭 없는 판단으로는 어디를 어떻게 고칠지 알 수 없기 때문이다","correct":true},{"t":"도율이를 이기고 싶기 때문이다","mis":"K6-1-u6-X45"},{"t":"「별로야」만으로 충분하기 때문이다","mis":"K6-1-u6-X06"},{"t":"⑤문단을 버리고 싶기 때문이다","mis":"K6-1-u6-X21"}],"explanation":["이기려는 게 아니에요.","까닭이 있어야 해요.","판단은 결과와 근거가 한 짝이에요."],"asset":{"type":"speech","turns":[{"who":"도율","text":"담희 글에 이상한 데가 세 군데나 있어. 이 글은 다 버리는 게 낫겠다."},{"who":"담희","text":"걸린 곳만 짚어 줘. 창문을 열자는 주장과 직접 센 기록도 틀렸어?"},{"who":"도율","text":"그건 아니야. 그리고 ⑤문단은 그냥 별로야."},{"who":"담희","text":"별로라고만 하면 어디를 고칠지 모르겠어. 왜 걸리는지 까닭을 말해 줄래?"}]}}'::jsonb),
