('g6_1_kor_u6_review_c#9','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C18',2,'mc','auto','담희 글 문단 ④의 이유가 걸리는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X10','K6-1-u6-X08','K6-1-u6-X18']::text[],false,'{"seq":9,"concept":"K6-1-u6-C18","difficulty":2,"kind":"mc","stem":"담희 글 문단 ④의 이유가 걸리는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"창문을 열어도 감기에 걸릴 수 있어 사실이 아니기 때문이다","correct":true},{"t":"창문 이야기가 아니기 때문이다","mis":"K6-1-u6-X10"},{"t":"문단이 짧기 때문이다","mis":"K6-1-u6-X08"},{"t":"감기는 누구나 알기 때문이다","mis":"K6-1-u6-X18"}],"explanation":["창문 이야기가 맞아요.","길이 문제가 아니에요.","실제로 일어나지 않는 일이에요 — 바르게는 「바깥 공기가 들어와 답답함이 줄어듭니다」처럼 말해요."],"asset":{"type":"passage","lines":["④ 셋째, 창문을 열어 두면 감기에 걸리지 않습니다.","옆 반 친구가 그렇게 말해 주었습니다.","⑤ 창문만 열면 교실의 모든 문제가 사라집니다.","⑥ 추운 날에는 잠깐만 열어도 됩니다. 쉬는 시간마다 창문을 열어 둡시다."],"title":"담희의 글 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb),
('g6_1_kor_u6_review_c#10','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C16',2,'mc','auto','「「답답하다」고 적은 친구가 날마다 줄었다」는 어느 이유를 받치나요?',ARRAY['K6-1-u6-X16']::text[],false,'{"seq":10,"concept":"K6-1-u6-C16","difficulty":2,"kind":"mc","stem":"「「답답하다」고 적은 친구가 날마다 줄었다」는 어느 이유를 받치나요?","options":[{"t":"바깥 공기가 들어와 교실 공기가 바뀐다","correct":true},{"t":"창문을 닫으면 조용하다","mis":"K6-1-u6-X16"},{"t":"감기에 걸리지 않는다","mis":"K6-1-u6-X16"},{"t":"모든 문제가 사라진다","mis":"K6-1-u6-X16"}],"explanation":["반대 쪽 이유예요.","사실이 아닌 이유예요.","같은 문단 ② 안에서 짝을 찾아요."],"asset":{"type":"passage","lines":["① 셋째 시간이 끝날 무렵이면 교실 공기가 답답해집니다.","쉬는 시간마다 창문을 열어 두면 좋겠습니다.","② 첫째, 바깥 공기가 들어와 교실 공기가 바뀝니다. 우리 반이 일주일 동안","쉬는 시간마다 창문을 열어 보니, 「답답하다」고 적은 친구가 날마다 줄었습니다.","③ 둘째, 창문을 닫아 두면 바깥 소리가 들어오지 않아 수업에 마음을 모을 수 있습니다."],"title":"담희의 글 「쉬는 시간마다 창문을 열어 둡시다」 — 앞부분 (흠을 일부러 넣은 글)"}}'::jsonb),
('g6_1_kor_u6_review_c#11','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C28',2,'mc','auto','「공부가 저절로 되는」은 거짓, 「영원히 마르지 않는」은 과장으로 가른 까닭은 어느 것인가요?',ARRAY['K6-1-u6-X24','K6-1-u6-X23','K6-1-u6-X25']::text[],false,'{"seq":11,"concept":"K6-1-u6-C28","difficulty":2,"kind":"mc","stem":"「공부가 저절로 되는」은 거짓, 「영원히 마르지 않는」은 과장으로 가른 까닭은 어느 것인가요?","options":[{"t":"앞은 형광펜에 없는 기능이고, 뒤는 있는 기능(잘 마르지 않음)을 부풀렸기 때문이다","correct":true},{"t":"앞의 글씨가 더 크기 때문이다","mis":"K6-1-u6-X24"},{"t":"뒤에 느낌표가 있기 때문이다","mis":"K6-1-u6-X23"},{"t":"둘 다 같은 것이기 때문이다","mis":"K6-1-u6-X25"}],"explanation":["크기로 가르지 않아요.","느낌표와 관계없어요.","기능이 실제로 있는지로 갈라요. (바로잡기: 형광펜에는 공부를 대신해 주는 기능이 없어요.) (바로잡기: 뚜껑을 열어 두면 잉크는 마를 수 있어요.)"],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb),
('g6_1_kor_u6_review_c#12','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C30',2,'ox','auto','안내문이나 주장하는 글도 부풀리거나 감출 수 있어요.',ARRAY['K6-1-u6-X29']::text[],false,'{"seq":12,"concept":"K6-1-u6-C30","difficulty":2,"kind":"ox","stem":"안내문이나 주장하는 글도 부풀리거나 감출 수 있어요.","answer":"O","reason_options":[{"t":"설득하려는 글이면 어디서든 일어날 수 있기 때문에","correct":true},{"t":"부풀리고 감추는 건 광고에서만 일어나기 때문에","mis":"K6-1-u6-X29"}],"mis":"K6-1-u6-X29","explanation":["광고만의 일이 아니에요.","어떤 글에도 세 물음을 대요.","설득하는 글이면 어디든요."]}'::jsonb),
('g6_1_kor_u6_review_c#13','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C36',2,'mc','auto','「갯벌은 언제든 걸어 들어가 놀아도 좋습니다」가 감춘 것은 어느 것인가요?',ARRAY['K6-1-u6-X27']::text[],false,'{"seq":13,"concept":"K6-1-u6-C36","difficulty":2,"kind":"mc","stem":"「갯벌은 언제든 걸어 들어가 놀아도 좋습니다」가 감춘 것은 어느 것인가요?","options":[{"t":"바닷물이 들어오는 때에는 위험하니 그때를 확인해야 한다는 점","correct":true},{"t":"갯벌이 넓다는 점","mis":"K6-1-u6-X27"},{"t":"갯벌에 게가 산다는 점","mis":"K6-1-u6-X27"},{"t":"감춘 것이 없다","mis":"K6-1-u6-X27"}],"explanation":["앞에서 밝혔어요.","그것도 밝혔어요.","알아야 할 것을 빼놓았어요 — 바르게는 「바닷물이 들어오는 때를 확인하고 어른과 함께 들어가야 합니다」예요. (바로잡기: 우리나라에는 모래 바닷가 · 바위 바닷가도 있어요.)"],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb),
