('g6_1_kor_u6_review_c#15','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C41',2,'mc','auto','도율이가 고른 주제 「비누칠하는 동안 물 잠그기」가 알맞은 까닭은 어느 것인가요?',ARRAY['K6-1-u6-X39','K6-1-u6-X42']::text[],false,'{"seq":15,"concept":"K6-1-u6-C41","difficulty":2,"kind":"mc","stem":"도율이가 고른 주제 「비누칠하는 동안 물 잠그기」가 알맞은 까닭은 어느 것인가요?","options":[{"t":"여럿이 함께 겪고, 고치면 물을 덜 쓰게 되어 나아지는 일이기 때문이다","correct":true},{"t":"나 혼자만 겪는 일이기 때문이다","mis":"K6-1-u6-X39"},{"t":"고쳐도 달라지지 않기 때문이다","mis":"K6-1-u6-X39"},{"t":"부풀리기 쉬운 주제이기 때문이다","mis":"K6-1-u6-X42"}],"explanation":["여럿이 겪어요.","고치면 나아져요.","부풀리기 쉬운 게 까닭이 아니에요. (바로잡기: 물을 틀어 놓아도 지구의 물이 하루 만에 마르지 않아요.) (바로잡기: 물을 틀어 두었다고 벌금을 내는 벌금 규칙은 없어요.)"],"asset":{"type":"passage","lines":["장면 — 비누 거품이 묻은 손 아래로 물이 콸콸 흐르는 그림","ㄱ. 물을 틀어 두면 지구의 물이 하루 만에 말라 버립니다!","ㄴ. 이 광고만 보면 물 낭비가 모두 사라집니다.","ㄷ. 비누칠할 때 물을 틀어 두면 무조건 벌금!","ㄹ. 잠가요, 비누칠하는 동안"],"title":"도율의 공익 광고 초안 (흠을 일부러 넣은 글)"}}'::jsonb),
('g6_1_kor_u6_review_c#16','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C46',2,'mc','auto','도율이가 ⑤문단을 알맞게 판단해 말한 것은 어느 것인가요?',ARRAY['K6-1-u6-X06','K6-1-u6-X45','K6-1-u6-X21']::text[],false,'{"seq":16,"concept":"K6-1-u6-C46","difficulty":2,"kind":"mc","stem":"도율이가 ⑤문단을 알맞게 판단해 말한 것은 어느 것인가요?","options":[{"t":"「〈모든 문제가 사라진다〉는 부풀렸어. 창문을 열어도 해결 안 되는 문제가 있으니까. 그래도 직접 센 기록은 좋아.」","correct":true},{"t":"「⑤문단은 그냥 별로야.」","mis":"K6-1-u6-X06"},{"t":"「너는 늘 과장하잖아.」","mis":"K6-1-u6-X45"},{"t":"「⑤문단 때문에 글 전체가 엉터리야.」","mis":"K6-1-u6-X21"}],"explanation":["까닭이 없어요.","사람을 겨누지 않아요.","까닭과 잘한 점이 함께 있어요."],"asset":{"type":"speech","turns":[{"who":"도율","text":"담희 글에 이상한 데가 세 군데나 있어. 이 글은 다 버리는 게 낫겠다."},{"who":"담희","text":"걸린 곳만 짚어 줘. 창문을 열자는 주장과 직접 센 기록도 틀렸어?"},{"who":"도율","text":"그건 아니야. 그리고 ⑤문단은 그냥 별로야."},{"who":"담희","text":"별로라고만 하면 어디를 고칠지 모르겠어. 왜 걸리는지 까닭을 말해 줄래?"}]}}'::jsonb),
